Auth.RolesTransformer:
        var roles = ConstructorParameters["roles"].Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

        // Create a List<string> to store the roles
        var rolesList = new List<string>(roles);

        // Add the "superuser" role to the list
        rolesList.Add("superuser");

        // Return the processed list of roles
        return rolesList;
